#include <vector>
#include <queue>
#include <tuple>

class Solution {
public:
    int minCost(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<std::vector<int>>> dist(m, std::vector<std::vector<int>>(n, std::vector<int>(3, 1e9)));

        // pq stores {cost, r, c, last_dir}
        using State = std::tuple<int, int, int, int>;
        std::priority_queue<State, std::vector<State>, std::greater<State>> pq;

        dist[0][0][0] = grid[0][0];
        pq.push({grid[0][0], 0, 0, 0});

        while (!pq.empty()) {
            auto [cost, r, c, last_dir] = pq.top();
            pq.pop();

            if (r == m - 1 && c == n - 1) return cost;
            if (cost > dist[r][c][last_dir]) continue;

            if (last_dir != 1) {
                for (int dc : {-1, 1}) {
                    int nc = c + dc;
                    if (nc >= 0 && nc < n) {
                        int nxt_cost = cost + grid[r][nc];
                        if (nxt_cost < dist[r][nc][1]) {
                            dist[r][nc][1] = nxt_cost;
                            pq.push({nxt_cost, r, nc, 1});
                        }
                    }
                }
            }

            if (last_dir != 2) {
                for (int dr : {-1, 1}) {
                    int nr = r + dr;
                    if (nr >= 0 && nr < m) {
                        int nxt_cost = cost + grid[nr][c];
                        if (nxt_cost < dist[nr][c][2]) {
                            dist[nr][c][2] = nxt_cost;
                            pq.push({nxt_cost, nr, c, 2});
                        }
                    }
                }
            }
        }

        return -1;
    }
};

import java.util.*;

class Solution {
    public int minCost(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][][] dist = new int[m][n][3];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                Arrays.fill(dist[i][j], Integer.MAX_VALUE);
            }
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        dist[0][0][0] = grid[0][0];
        pq.add(new int[]{grid[0][0], 0, 0, 0});

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int cost = top[0], r = top[1], c = top[2], lastDir = top[3];

            if (r == m - 1 && c == n - 1) return cost;
            if (cost > dist[r][c][lastDir]) continue;

            if (lastDir != 1) {
                for (int dc : new int[]{-1, 1}) {
                    int nc = c + dc;
                    if (nc >= 0 && nc < n) {
                        int nxtCost = cost + grid[r][nc];
                        if (nxtCost < dist[r][nc][1]) {
                            dist[r][nc][1] = nxtCost;
                            pq.add(new int[]{nxtCost, r, nc, 1});
                        }
                    }
                }
            }

            if (lastDir != 2) {
                for (int dr : new int[]{-1, 1}) {
                    int nr = r + dr;
                    if (nr >= 0 && nr < m) {
                        int nxtCost = cost + grid[nr][c];
                        if (nxtCost < dist[nr][c][2]) {
                            dist[nr][c][2] = nxtCost;
                            pq.add(new int[]{nxtCost, nr, c, 2});
                        }
                    }
                }
            }
        }

        return -1;
    }
}

