var minCost = function(grid) {
    const m = grid.length, n = grid[0].length;
    const dist = Array.from({ length: m }, () => Array.from({ length: n }, () => new Int32Array(3).fill(1e9)));

    // Min-priority queue simulated via flat array sorted or heap
    const heap = [[grid[0][0], 0, 0, 0]];
    dist[0][0][0] = grid[0][0];

    while (heap.length > 0) {
        heap.sort((a, b) => a[0] - b[0]);
        const [cost, r, c, lastDir] = heap.shift();

        if (r === m - 1 && c === n - 1) return cost;
        if (cost > dist[r][c][lastDir]) continue;

        if (lastDir !== 1) {
            for (const dc of [-1, 1]) {
                const nc = c + dc;
                if (nc >= 0 && nc < n) {
                    const nxtCost = cost + grid[r][nc];
                    if (nxtCost < dist[r][nc][1]) {
                        dist[r][nc][1] = nxtCost;
                        heap.push([nxtCost, r, nc, 1]);
                    }
                }
            }
        }

        if (lastDir !== 2) {
            for (const dr of [-1, 1]) {
                const nr = r + dr;
                if (nr >= 0 && nr < m) {
                    const nxtCost = cost + grid[nr][c];
                    if (nxtCost < dist[nr][c][2]) {
                        dist[nr][c][2] = nxtCost;
                        heap.push([nxtCost, nr, c, 2]);
                    }
                }
            }
        }
    }

    return -1;
};
